<?php

declare(strict_types=1);

namespace App\Billing\Sale\Void;

use App\Inventory\Core\Dto\MovementDraft;
use App\Inventory\Core\Enum\StockMovementType;
use App\Inventory\Core\Service\InventoryService;
use App\Sales\Entity\SaleRecord;
use Doctrine\DBAL\Connection;
use Psr\Log\LoggerInterface;

/**
 * Reverses inventory movements when a sale is voided.
 *
 * Finds all SALE_OUT / MANUAL_OUT movements generated by the original sale
 * (source_type IN ('SALE','LEGACY_MOVIMIENTO_ITEM') AND source_id LIKE ':saleId:%')
 * and generates a VOID_REVERSAL movement of equal magnitude in the opposite direction.
 *
 * Idempotent: if the reversal was already applied, the idempotency_key in
 * InventoryService::recordMovement() silently skips the duplicate.
 */
final readonly class StockVoidReverser implements StockVoidReverserInterface
{
    public function __construct(
        private InventoryService $inventoryService,
        private Connection $connection,
        private LoggerInterface $logger,
    ) {
    }

    /**
     * Reverse all stock movements for the given sale.
     *
     * @throws \Doctrine\DBAL\Exception
     */
    public function reverse(SaleRecord $sale): void
    {
        $saleId = (string) $sale->getId();

        $movements = $this->connection->fetchAllAssociative(
            <<<'SQL'
            SELECT id, warehouse_id, product_id, qty_delta_base, unit_id
            FROM stock_movements
            WHERE source_type IN ('SALE', 'LEGACY_MOVIMIENTO_ITEM')
              AND source_id LIKE :prefix
              AND movement_type IN ('SALE_OUT', 'MANUAL_OUT')
            SQL,
            ['prefix' => $saleId . '%'],
        );

        if ($movements === []) {
            $this->logger->info('StockVoidReverser: no movements found for sale', ['sale_id' => $saleId]);

            return;
        }

        foreach ($movements as $row) {
            // Invert the delta: if the original was -5, the reversal is +5
            $originalDelta = (string) $row['qty_delta_base'];
            $reversalDelta = str_starts_with($originalDelta, '-')
                ? ltrim($originalDelta, '-')           // negative → positive
                : '-' . $originalDelta;               // positive → negative (safety)

            $absQty = ltrim(ltrim($reversalDelta, '+'), '-');

            try {
                $this->inventoryService->recordMovement(new MovementDraft(
                    warehouseId:  $row['warehouse_id'],
                    productId:    $row['product_id'],
                    movementType: StockMovementType::VOID_REVERSAL,
                    qtyDeltaBase: $reversalDelta,
                    unitId:       (int) ($row['unit_id'] ?? 0),
                    qtyOriginal:  $absQty,
                    sourceType:   'VOID',
                    sourceId:     'VOID:' . $row['id'],
                    note:         'Reversa por anulación de venta ' . $saleId,
                ));
            } catch (\Throwable $e) {
                // Log but don't abort — partial reversals are better than none.
                // The reconciliation service will detect any remaining drift.
                $this->logger->error('StockVoidReverser: failed to reverse movement', [
                    'movement_id' => $row['id'],
                    'sale_id'     => $saleId,
                    'error'       => $e->getMessage(),
                ]);
            }
        }

        $this->logger->info('StockVoidReverser: reversed movements for sale', [
            'sale_id' => $saleId,
            'count'   => count($movements),
        ]);
    }
}
